"""Task-5 QGIS handoff without a QGIS runtime dependency."""

from __future__ import annotations

from pathlib import Path


def qgis_layer_source(output_dir: str | Path) -> str:
    """Return the GeoJSON layer generated by Task 5 for GEOAgent to load."""
    return str(Path(output_dir).resolve() / "fiber_links.geojson")
